-- ─── خدمة اطلب التوكتوك + سواقين تجريبيين (demo) ───
-- Adds service 43 (اطلب التوكتوك) and 14 fictional demo tuk-tuk drivers (ids 148-161).
-- Insert-only for these new ids; existing rows are untouched. Idempotent (on conflict do update).
-- A backup of the live services/providers tables before this change is in supabase/backups/2026-11-06-pre-tuktuk/.
-- Apply in the Supabase SQL Editor (or the Management API), then hard-refresh the app.

on conflict (id) do update set cat = excluded.cat, emoji = excluded.emoji, name = excluded.name, description = excluded.description, time = excluded.time, price = excluded.price, numeric_price = excluded.numeric_price, price_type = excluded.price_type, rating = excluded.rating, badge = excluded.badge, featured = excluded.featured, subject = excluded.subject, options = excluded.options, hidden = excluded.hidden, keywords = excluded.keywords, quantity = excluded.quantity;

on conflict (id) do update set kind = excluded.kind, service_id = excluded.service_id, name = excluded.name, gender = excluded.gender, photo = excluded.photo, subject = excluded.subject, stages = excluded.stages, specialty = excluded.specialty, role = excluded.role, experience_years = excluded.experience_years, rating = excluded.rating, reviews = excluded.reviews, price = excluded.price, numeric_price = excluded.numeric_price, price_type = excluded.price_type, area = excluded.area, village = excluded.village, bio = excluded.bio, modes = excluded.modes, group_price = excluded.group_price, inspection_fee = excluded.inspection_fee, delivery_fee = excluded.delivery_fee, groups = excluded.groups, active = excluded.active;

